@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings

<nav class="settings-sidebar">
    <h3 class="sidebar-title">Settings</h3>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (StatusMessage is not null)
    {
        <div class="toast success">@StatusMessage</div>
    }

    <div class="profile-form">
        <div class="avatar-preview">
            <img src="@AvatarUrl" alt="Avatar preview" class="avatar-image" />
            <p class="avatar-url-label">Avatar URL:</p>
            <input type="text" @bind="AvatarUrl" class="form-input" />
        </div>

        <div class="form-group">
            <label class="form-label">Display Name</label>
            <input type="text" @bind="DisplayName" class="form-input" />
        </div>

        <div class="form-group">
            <label class="form-label">Email</label>
            <input type="email" @bind="Email" class="form-input" />
        </div>

        <div class="form-group">
            <label class="form-label">Bio</label>
            <textarea @bind="Bio" class="form-input form-textarea" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        StatusMessage = "Profile saved successfully!";
        _ = ClearStatusAfterDelay();
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        StatusMessage = null;
    }

    private async Task ClearStatusAfterDelay()
    {
        await Task.Delay(3000);
        StatusMessage = null;
        StateHasChanged();
    }
}

@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="EmailNotifications" class="toggle-input" />
                <span class="toggle-switch"></span>
                Email Notifications
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="PushNotifications" class="toggle-input" />
                <span class="toggle-switch"></span>
                Push Notifications
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" @bind="WeeklyDigest" class="toggle-input" />
                <span class="toggle-switch"></span>
                Weekly Digest
            </label>
        </div>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = new();

    private static readonly string[] AllChannels = { "general", "announcements", "marketing", "engineering", "design", "support" };

    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
    }
}

@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Services

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span>Change Password</span>
            <span class="panel-toggle">@(PasswordPanelOpen ? "▲" : "▼")</span>
        </button>
        @if (PasswordPanelOpen)
        {
            <div class="panel-body">
                @if (PasswordMessage is not null)
                {
                    <div class="toast @(PasswordError ? "error" : "success")">@PasswordMessage</div>
                }
                <div class="form-group">
                    <label class="form-label">Current Password</label>
                    <input type="password" @bind="CurrentPassword" class="form-input" />
                </div>
                <div class="form-group">
                    <label class="form-label">New Password</label>
                    <input type="password" @bind="NewPassword" class="form-input" />
                </div>
                <div class="form-group">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" @bind="ConfirmPassword" class="form-input" />
                </div>
                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" disabled class="toggle-input" />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
            </label>
            <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="meta-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    @if (Settings?.Sessions.Any() == true)
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    <!-- Revoke Confirmation Dialog -->
    @if (SessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordMessage;
    private bool PasswordError;
    private bool TwoFactorEnabled;
    private ActiveSession? SessionToRevoke;

    private const string CurrentSessionId = "sess-1";

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            TwoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordMessage = "All fields are required.";
            PasswordError = true;
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordMessage = "New passwords do not match.";
            PasswordError = true;
            return;
        }

        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        PasswordMessage = "Password updated successfully!";
        PasswordError = false;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Services

<div class="settings-section">
    <h2>Appearance</h2>

    <div class="form-group">
        <label class="form-label">Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    @theme
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label class="form-label">Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    @size
                </label>
            }
        </div>
    </div>

    <div class="form-group">
        <label class="form-label">Language</label>
        <select @bind="Language" class="form-input form-select">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
            <option value="Chinese">Chinese</option>
        </select>
    </div>

    <div class="toggle-item">
        <label class="toggle-label">
            <input type="checkbox" @bind="CompactMode" class="toggle-input" />
            <span class="toggle-switch"></span>
            Compact Mode
        </label>
    </div>

    <!-- Live Preview -->
    <div class="appearance-preview @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p class="preview-text">This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Dashboard items will appear in this style.</p>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="Save">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;

    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{Theme.ToLower()} preview-font-{FontSize.ToLower()}";
        if (CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task Save()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
    }
}

