@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings

<nav class="settings-sidebar">
    <h3 class="sidebar-title">Settings</h3>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (StatusMessage is not null)
    {
        <div class="toast success">@StatusMessage</div>
    }

    <div class="profile-form">
        <div class="avatar-preview">
            <img src="@AvatarUrl" alt="Avatar preview" class="avatar-image" />
            <p class="avatar-url-label">Avatar URL:</p>
            <input type="text" @bind="AvatarUrl" class="form-input" />
        </div>

        <div class="form-group">
            <label class="form-label">Display Name</label>
            <input type="text" @bind="DisplayName" class="form-input" />
        </div>

        <div class="form-group">
            <label class="form-label">Email</label>
            <input type="email" @bind="Email" class="form-input" />
        </div>

        <div class="form-group">
            <label class="form-label">Bio</label>
            <textarea @bind="Bio" class="form-input form-textarea" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        StatusMessage = "Profile saved successfully!";
        _ = ClearStatusAfterDelay();
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        StatusMessage = null;
    }

    private async Task ClearStatusAfterDelay()
    {
        await Task.Delay(3000);
        StatusMessage = null;
        StateHasChanged();
    }
}

