<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span>Change Password</span>
            <span class="panel-toggle">@(PasswordPanelOpen ? "▲" : "▼")</span>
        </button>
        @if (PasswordPanelOpen)
        {
            <div class="panel-body">
                @if (PasswordMessage is not null)
                {
                    <div class="toast @(PasswordError ? "error" : "success")">@PasswordMessage</div>
                }
                <div class="form-group">
                    <label class="form-label">Current Password</label>
                    <input type="password" @bind="CurrentPassword" class="form-input" />
                </div>
                <div class="form-group">
                    <label class="form-label">New Password</label>
                    <input type="password" @bind="NewPassword" class="form-input" />
                </div>
                <div class="form-group">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" @bind="ConfirmPassword" class="form-input" />
                </div>
                <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="security-item">
        <div class="toggle-item">
            <label class="toggle-label">
                <input type="checkbox" checked="@TwoFactorEnabled" disabled class="toggle-input" />
                <span class="toggle-switch"></span>
                Two-Factor Authentication
            </label>
            <span class="status-indicator @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="meta-text">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    @if (Settings?.Sessions.Any() == true)
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    <!-- Revoke Confirmation Dialog -->
    @if (SessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordMessage;
    private bool PasswordError;
    private bool TwoFactorEnabled;
    private ActiveSession? SessionToRevoke;

    private const string CurrentSessionId = "sess-1";

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            TwoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordMessage = "All fields are required.";
            PasswordError = true;
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordMessage = "New passwords do not match.";
            PasswordError = true;
            return;
        }

        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        PasswordMessage = "Password updated successfully!";
        PasswordError = false;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

