@page "/settings"
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Components.Pages.Settings
@using sv_0a93194e0ee348c9b361f9de2322ef2c.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @if (loading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@profile" OnSave="SaveProfile" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@notifications" OnSave="SaveNotifications" />
                    break;
                case "Security":
                    <SecuritySection Settings="@security"
                                     OnChangePassword="ChangePassword"
                                     OnRevokeSession="RevokeSession" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@appearance" OnSave="SaveAppearance" />
                    break;
            }
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool loading = true;

    private UserProfile? profile;
    private NotificationPrefs? notifications;
    private SecuritySettings? security;
    private AppearanceSettings? appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        loading = false;
    }

    private async Task LoadAllSettings()
    {
        profile = await SettingsService.GetProfileAsync();
        notifications = await SettingsService.GetNotificationPrefsAsync();
        security = await SettingsService.GetSecuritySettingsAsync();
        appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }

    private async Task SaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotifications(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notifications = updated;
    }

    private async Task ChangePassword((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearance = updated;
    }
}

