.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e2e8f0;
    margin-bottom: 0.5rem;
}

.avatar-url-label {
    font-size: 0.8rem;
    color: #718096;
    margin: 0.5rem 0 0.25rem;
}

