+}
+
+/* Avatar */
+.avatar-preview {
+    margin-bottom: 1.5rem;
+    text-align: center;
+}
+
+.avatar-image {
+    width: 96px;
+    height: 96px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #e2e8f0;
+    margin-bottom: 0.5rem;
+}
+
+.avatar-url-label {
+    font-size: 0.8rem;
+    color: #718096;
+    margin: 0.5rem 0 0.25rem;
+}
+
+/* Toggles */
+.toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+.toggle-item {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.5rem 0;
+}
+
+.toggle-label {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    cursor: pointer;
+    font-size: 0.95rem;
+    color: #2d3748;
+}
+
+.toggle-input {
+    width: 18px;
+    height: 18px;
+    accent-color: #3182ce;
+}
+
+/* Channel List */
+.channel-list {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+    padding: 0.5rem 0;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    font-size: 0.9rem;
+    color: #4a5568;
+    cursor: pointer;
+}
+
+/* Expandable Panel */
+.expandable-panel {
+    border: 1px solid #e2e8f0;
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    width: 100%;
+    padding: 1rem 1.25rem;
+    background: #f7fafc;
+    border: none;
+    cursor: pointer;
+    font-size: 0.95rem;
+    font-weight: 500;
+    color: #2d3748;
+}
+
+.panel-header:hover {
+    background: #edf2f7;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e2e8f0;
+}
+
+/* Security Items */
+.security-item {
+    padding: 1rem 0;
+    border-bottom: 1px solid #edf2f7;
+    margin-bottom: 1rem;
+}
+
+.status-indicator {
+    font-size: 0.8rem;
+    font-weight: 500;
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+}
+
+.status-enabled {
+    background: #c6f6d5;
+    color: #22543d;
+}
+
+.status-disabled {
+    background: #fed7d7;
+    color: #742a2a;
+}
+
+.meta-text {
+    font-size: 0.8rem;
+    color: #718096;
+    margin: 0.5rem 0 0;
+}
+
+.current-badge {
+    font-size: 0.75rem;
+    background: #bee3f8;
+    color: #2a4365;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th {
+    text-align: left;
+    padding: 0.6rem 0.75rem;
+    background: #f7fafc;
+    color: #4a5568;
+    font-weight: 500;
+    border-bottom: 2px solid #e2e8f0;
+}
+
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    border-bottom: 1px solid #edf2f7;
+    color: #2d3748;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    border-radius: 12px;
+    padding: 1.5rem 2rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
+}
+
+.dialog h4 {
+    margin: 0 0 0.75rem;
+    color: #1a202c;
+}
+
+.dialog p {
+    color: #4a5568;
+    font-size: 0.9rem;
+    margin-bottom: 1.25rem;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-size: 0.9rem;
+    color: #2d3748;
+}
+
+/* Appearance Preview */
+.appearance-preview {
+    margin: 1.5rem 0;
+    padding: 1.5rem;
+    border: 1px solid #e2e8f0;
+    border-radius: 8px;
+    transition: all 0.2s ease;
+}
+
+.appearance-preview h4 {
+    margin: 0 0 0.5rem;
+}
+
+.preview-text {
+    color: #4a5568;
+    margin-bottom: 0.75rem;
+}
+
+.preview-card {
+    background: #f7fafc;
+    padding: 1rem;
+    border-radius: 6px;
+    border: 1px solid #e2e8f0;
+}
+
+.preview-card p {
+    margin: 0.4rem 0 0;
+    font-size: 0.9rem;
+    color: #718096;
+}
+
+/* Preview Theme Variants */
+.preview-theme-dark {
+    background: #1a202c;
+    border-color: #4a5568;
+    color: #e2e8f0;
+}
+
+.preview-theme-dark .preview-text {
+    color: #a0aec0;
+}
+
+.preview-theme-dark .preview-card {
+    background: #2d3748;
+    border-color: #4a5568;
+}
+
+.preview-theme-dark .preview-card p {
+    color: #a0aec0;
+}
+
+.preview-theme-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1a202c 50%);
+    border-color: #a0aec0;
+}
+
+/* Preview Font Size Variants */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.15rem;
+}
+
+/* Preview Compact */
+.preview-compact {
+    padding: 0.75rem;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+}
+
+/* Loading */
+.loading-spinner {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    padding: 3rem;
+    color: #718096;
+    font-size: 1rem;
+}
+

